class StockPortfolioTracker:
    # Replace magic number 0 with symbolic constant
    ZERO_QUANTITY = 0

    def __init__(self, cash_balance):
        self.portfolio = []
        self.cash_balance = cash_balance

    def add_stock(self, stock):
        existing_stock = self._find_stock_by_name(stock['name'])
        if existing_stock is not None:
            existing_stock['quantity'] += stock['quantity']
            return

        self.portfolio.append(stock)

    def _find_stock_by_name(self, name):
        for pf in self.portfolio:
            if pf['name'] == name:
                return pf
        return None

    def remove_stock(self, stock):
        existing_stock = self._find_stock_by_name(stock['name'])
        if existing_stock is None or existing_stock['quantity'] < stock['quantity']:
            return False

        existing_stock['quantity'] -= stock['quantity']
        if existing_stock['quantity'] == self.ZERO_QUANTITY:
            self.portfolio.remove(existing_stock)
        return True

    def buy_stock(self, stock):
        cost = self._calculate_stock_cost(stock)
        if cost > self.cash_balance:
            return False

        self.add_stock(stock)
        self.cash_balance -= cost
        return True

    def sell_stock(self, stock):
        if not self.remove_stock(stock):
            return False

        self.cash_balance += self._calculate_stock_cost(stock)
        return True

    def _calculate_stock_cost(self, stock):
        return stock['price'] * stock['quantity']

    def calculate_portfolio_value(self):
        total_value = self.cash_balance
        for stock in self.portfolio:
            total_value += self._calculate_stock_cost(stock)
        return total_value

    def get_portfolio_summary(self):
        summary = []
        for stock in self.portfolio:
            summary.append({
                "name": stock["name"],
                "value": self._calculate_stock_cost(stock)
            })
        total_value = self.calculate_portfolio_value()
        return total_value, summary

    def get_stock_value(self, stock):
        return self._calculate_stock_cost(stock)
